export interface PageData {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

export interface Page {
  slug: string;
  sourcePath: string;
  data: PageData;
  body: string;
  html: string;
  outputFile: string;
}

import matter from 'gray-matter';
import MarkdownIt from 'markdown-it';
import type { PageData } from './types';

export interface ParsedMarkdown {
  data: PageData;
  body: string;
}

const markdown = new MarkdownIt({ html: true, linkify: true, typographer: true });

export function parseMarkdown(raw: string): ParsedMarkdown {
  const parsed = matter(raw);
  const data: PageData = parsed.data && typeof parsed.data === 'object'
    ? (parsed.data as PageData)
    : {};
  return { data, body: parsed.content.trim() };
}

export function renderMarkdown(source: string): string {
  return markdown.render(source);
}

import type { Page, PageData } from './types';

const STYLES = `
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: #1f2933;
  background: #ffffff;
  line-height: 1.6;
}
.container { max-width: 760px; margin: 0 auto; padding: 2rem 1.5rem 4rem; }
a { color: #2563eb; text-decoration: none; }
a:hover { text-decoration: underline; }
.site-header { border-bottom: 1px solid #e4e7eb; margin-bottom: 1.5rem; padding-bottom: 1rem; }
h1.title { margin: 0.25rem 0 0.5rem; }
.back { font-size: 0.9rem; }
.meta { color: #52606d; font-size: 0.9rem; }
.date { margin-right: 0.5rem; }
.tag {
  display: inline-block;
  background: #eff6ff;
  color: #1e40af;
  border: 1px solid #bfdbfe;
  border-radius: 999px;
  padding: 0.1rem 0.6rem;
  font-size: 0.8rem;
  margin-right: 0.4rem;
}
main { margin-top: 1.5rem; }
main img { max-width: 100%; }
.page-list { list-style: none; margin: 0; padding: 0; }
.page-list .entry { padding: 0.75rem 0; border-bottom: 1px solid #e4e7eb; }
.page-list .entry:last-child { border-bottom: none; }
.entry-title { margin: 0 0 0.25rem; font-size: 1.25rem; }
footer { margin-top: 3rem; padding-top: 1rem; border-top: 1px solid #e4e7eb; color: #52606d; font-size: 0.85rem; }
`;

export function escapeHtml(value: unknown): string {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function pageTitle(data: PageData, fallback: string): string {
  const title = data && data.title && String(data.title).trim();
  return title ? title : fallback;
}

function renderMeta(page: Pick<Page, 'data'>): string {
  const parts: string[] = [];
  if (page.data.date) {
    parts.push(`<span class="date">${escapeHtml(page.data.date)}</span>`);
  }
  const tags = Array.isArray(page.data.tags) ? page.data.tags.map(String) : [];
  if (tags.length > 0) {
    const rendered = tags.map((t) => `<span class="tag">${escapeHtml(t)}</span>`).join('');
    parts.push(`<span class="tags">${rendered}</span>`);
  }
  return parts.join(' ');
}

export function buildPageHtml(page: Page): string {
  const title = pageTitle(page.data, page.slug);
  const meta = renderMeta(page);
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>${STYLES}</style>
</head>
<body>
  <div class="container">
    <header class="site-header">
      <a class="back" href="./index.html">&larr; All pages</a>
      <h1 class="title">${escapeHtml(title)}</h1>
      ${meta ? `<p class="meta">${meta}</p>` : ''}
    </header>
    <main>
${page.html}
    </main>
    <footer>Generated by ssg</footer>
  </div>
</body>
</html>
`;
}

export function buildIndexHtml(pages: Page[]): string {
  const entries = pages
    .map((page) => {
      const title = pageTitle(page.data, page.slug);
      const meta = renderMeta(page);
      return `    <li class="entry">
      <a href="./${escapeHtml(page.outputFile)}"><h2 class="entry-title">${escapeHtml(title)}</h2></a>
      ${meta ? `<p class="meta">${meta}</p>` : ''}
    </li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>All pages</title>
  <style>${STYLES}</style>
</head>
<body>
  <div class="container">
    <header class="site-header">
      <h1 class="title">All pages</h1>
    </header>
    <ul class="page-list">
${entries}
    </ul>
    <footer>Generated by ssg</footer>
  </div>
</body>
</html>
`;
}

#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { parseMarkdown, renderMarkdown } from './parser';
import { buildPageHtml, buildIndexHtml } from './generator';
import type { Page } from './types';

export interface CliOptions {
  command: string;
  contentDir: string;
  outputDir: string;
}

export interface SiteBuildResult {
  outputDir: string;
  pages: Page[];
  indexFile: string;
}

const HELP = `ssg — a tiny static site generator

Usage:
  ssg build [options]

Options:
  --content <dir>   Directory containing Markdown files (default: ./content)
  --output <dir>    Directory where the site is written (default: ./dist)
  --help            Show this help message
  --version         Show the version number
`;

const VERSION = '1.0.0';

export function parseArgs(argv: string[]): CliOptions {
  let command = '';
  let contentDir = 'content';
  let outputDir = 'dist';

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--content') {
      contentDir = argv[++i];
    } else if (arg.startsWith('--content=')) {
      contentDir = arg.slice('--content='.length);
    } else if (arg === '--output') {
      outputDir = argv[++i];
    } else if (arg.startsWith('--output=')) {
      outputDir = arg.slice('--output='.length);
    } else if (arg === '--help' || arg === '-h') {
      command = 'help';
    } else if (arg === '--version' || arg === '-v') {
      command = 'version';
    } else {
      command = arg;
    }
  }

  if (!command) {
    command = 'build';
  }

  return { command, contentDir, outputDir };
}

export function slugify(fileName: string): string {
  const slug = fileName
    .toLowerCase()
    .replace(/\.[^.]+$/, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return slug || 'page';
}

export function buildSite(contentDir: string, outputDir: string): SiteBuildResult {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`content directory not found: ${contentDir}`);
  }

  const mdFiles = fs
    .readdirSync(contentDir)
    .filter((f) => {
      if (!fs.statSync(path.join(contentDir, f)).isFile()) return false;
      return f.toLowerCase().endsWith('.md');
    })
    .sort();

  if (mdFiles.length === 0) {
    throw new Error(`no markdown files found in: ${contentDir}`);
  }

  fs.mkdirSync(outputDir, { recursive: true });

  const pages: Page[] = mdFiles.map((file) => {
    const raw = fs.readFileSync(path.join(contentDir, file), 'utf-8');
    const { data, body } = parseMarkdown(raw);
    const slug = slugify(file);
    return {
      slug,
      sourcePath: file,
      data,
      body,
      html: renderMarkdown(body),
      outputFile: slug === 'index' ? 'index-page.html' : `${slug}.html`,
    };
  });

  pages.sort((a, b) => {
    const dateA = a.data.date ? String(a.data.date) : '';
    const dateB = b.data.date ? String(b.data.date) : '';
    if (dateA !== dateB) {
      return dateA > dateB ? -1 : 1;
    }
    return a.slug.localeCompare(b.slug);
  });

  for (const page of pages) {
    fs.writeFileSync(path.join(outputDir, page.outputFile), buildPageHtml(page), 'utf-8');
  }

  const indexFile = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexFile, buildIndexHtml(pages), 'utf-8');

  return { outputDir, pages, indexFile };
}

export function runCli(argv: string[]): number {
  const options = parseArgs(argv);

  if (options.command === 'help') {
    process.stdout.write(HELP);
    return 0;
  }
  if (options.command === 'version') {
    process.stdout.write(`${VERSION}\n`);
    return 0;
  }
  if (options.command !== 'build') {
    process.stderr.write(`ssg: unknown command "${options.command}"\n\nRun "ssg --help" for usage.\n`);
    return 1;
  }

  try {
    const result = buildSite(options.contentDir, options.outputDir);
    process.stdout.write(`Generated ${result.pages.length} page(s) in ${result.outputDir}\n`);
    return 0;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    process.stderr.write(`ssg: build failed: ${message}\n`);
    return 1;
  }
}

if (require.main === module) {
  process.exitCode = runCli(process.argv.slice(2));
}

export { parseMarkdown, renderMarkdown } from './parser';
export { buildPageHtml, buildIndexHtml, escapeHtml, pageTitle } from './generator';
export { buildSite, parseArgs, runCli, slugify } from './cli';
export type { CliOptions, SiteBuildResult } from './cli';
export type { Page, PageData } from './types';

import { parseMarkdown, renderMarkdown } from '../src/parser';

describe('parseMarkdown', () => {
  it('strips YAML frontmatter delimited by --- and exposes the data', () => {
    const raw = `---
title: Hello World
date: 2024-01-15
tags: [intro, guide]
---
# Heading

Some **bold** text.
`;

    const { data, body } = parseMarkdown(raw);

    expect(data.title).toBe('Hello World');
    expect(data.date).toBe('2024-01-15');
    expect(data.tags).toEqual(['intro', 'guide']);
    expect(body).toContain('# Heading');
    expect(body).toContain('Some **bold** text.');
    expect(body).not.toContain('---');
    expect(body).not.toContain('title: Hello World');
  });

  it('supports string tag lists', () => {
    const raw = `---
title: Tags
tags: one, two, three
---
Body
`;

    const { data } = parseMarkdown(raw);
    expect(data.title).toBe('Tags');
    expect(String(data.tags)).toContain('one');
  });

  it('returns empty data and full body when there is no frontmatter', () => {
    const { data, body } = parseMarkdown('# Just a heading\n\nplain text');

    expect(data).toEqual({});
    expect(body).toContain('# Just a heading');
    expect(body).toContain('plain text');
  });

  it('returns empty data for a doc that is only frontmatter', () => {
    const raw = `---
title: Only Metadata
---
`;

    const { data, body } = parseMarkdown(raw);
    expect(data.title).toBe('Only Metadata');
    expect(body).toBe('');
  });

  it('leaves the frontmatter out of the trimmed body', () => {
    const raw = `---
title: A
---
First line

Second line.
`;

    const { body } = parseMarkdown(raw);
    expect(body.split('\n').length).toBeGreaterThan(1);
    expect(body.startsWith('First line')).toBe(true);
  });
});

describe('renderMarkdown', () => {
  it('renders headings, emphasis and links to HTML', () => {
    const html = renderMarkdown('# Big Title\n\nA paragraph with **bold** and [a link](http://x.test).');

    expect(html).toContain('<h1>Big Title</h1>');
    expect(html).toContain('<strong>bold</strong>');
    expect(html).toContain('<a href="http://x.test">a link</a>');
  });

  it('renders lists', () => {
    const html = renderMarkdown('- one\n- two\n- three');
    expect(html).toContain('<li>one</li>');
    expect(html).toContain('<li>two</li>');
    expect(html).toContain('<li>three</li>');
  });

  it('renders empty source to empty output', () => {
    expect(renderMarkdown('')).toBe('');
  });
});

import { buildIndexHtml, buildPageHtml, pageTitle } from '../src/generator';
import type { Page } from '../src/types';

function makePage(overrides: Partial<Page> = {}): Page {
  return {
    slug: 'post',
    sourcePath: 'post.md',
    data: {},
    body: '# Hello',
    html: '<h1>Hello</h1>',
    outputFile: 'post.html',
    ...overrides,
  };
}

describe('pageTitle', () => {
  it('uses the frontmatter title when present', () => {
    expect(pageTitle({ title: 'My Post' }, 'post')).toBe('My Post');
  });

  it('falls back to the slug when no title is present', () => {
    expect(pageTitle({}, 'post')).toBe('post');
  });

  it('ignores whitespace-only titles', () => {
    expect(pageTitle({ title: '   ' }, 'post')).toBe('post');
  });
});

describe('buildPageHtml', () => {
  it('produces a complete self-contained HTML document', () => {
    const html = buildPageHtml(
      makePage({
        data: { title: 'About Me', date: '2024-03-01', tags: ['meta', 'intro'] },
        html: '<p>Hello there</p>',
      }),
    );

    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<title>About Me</title>');
    expect(html).toContain('<h1 class="title">About Me</h1>');
    expect(html).toContain('<span class="date">2024-03-01</span>');
    expect(html).toContain('<span class="tag">meta</span>');
    expect(html).toContain('<span class="tag">intro</span>');
    expect(html).toContain('<p>Hello there</p>');
    expect(html).toContain('<style>');
    expect(html).toContain('</style>');
    expect(html).toContain('<a class="back" href="./index.html">');
  });

  it('falls back to the slug in the <title> when no title is set', () => {
    const html = buildPageHtml(makePage({ data: {}, html: '<p>body</p>' }));
    expect(html).toContain('<title>post</title>');
  });

  it('does not emit metadata when none is present', () => {
    const html = buildPageHtml(makePage({ data: {}, html: '<p>body</p>' }));
    expect(html).not.toContain('<p class="meta">');
  });

  it('escapes HTML in the title', () => {
    const html = buildPageHtml(makePage({ data: { title: '<script>alert(1)</script>' } }));
    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).toContain('&lt;script&gt;');
  });
});

describe('buildIndexHtml', () => {
  const pages: Page[] = [
    makePage({
      slug: 'about',
      outputFile: 'about.html',
      data: { title: 'About', date: '2024-01-01' },
    }),
    makePage({
      slug: 'blog',
      outputFile: 'blog.html',
      data: { title: 'Blog', tags: ['news'] },
    }),
    makePage({ slug: 'plain', outputFile: 'plain.html', data: {} }),
  ];

  it('lists every page with a link to its output file', () => {
    const html = buildIndexHtml(pages);

    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<title>All pages</title>');
    expect(html).toContain('<a href="./about.html"><h2 class="entry-title">About</h2></a>');
    expect(html).toContain('<a href="./blog.html"><h2 class="entry-title">Blog</h2></a>');
